const crypto = require('crypto');

const HMAC_SECRET   = $env['N8N_WEBHOOK_HMAC_SECRET'];
const MAX_SKEW_SECS = 300;

const item    = $input.first();
const headers = item.json.headers || {};

const sigHeader = headers['x-eduai-signature-256']   || '';
const tsHeader  = headers['x-eduai-timestamp']       || '';
const idempKey  = headers['x-eduai-idempotency-key'] || '';

const nowSecs = Math.floor(Date.now() / 1000);
const tsSecs  = parseInt(tsHeader, 10);
if (isNaN(tsSecs) || Math.abs(nowSecs - tsSecs) > MAX_SKEW_SECS) {
  throw new Error(`Timestamp rejected: skew=${nowSecs - tsSecs}s`);
}

const rawBody  = item.json.rawBody || JSON.stringify(item.json.body);
const expected = 'sha256=' + crypto.createHmac('sha256', HMAC_SECRET).update(rawBody, 'utf8').digest('hex');
const sigBuf = Buffer.from(sigHeader);
const expBuf = Buffer.from(expected);
if (sigBuf.length !== expBuf.length || !crypto.timingSafeEqual(sigBuf, expBuf)) {
  throw new Error('Signature verification failed');
}

const body = typeof rawBody === 'string' ? JSON.parse(rawBody) : rawBody;
return [{ json: { ...body, _idempotency_key: idempKey, _verified: true } }];

// ── Deliverable 2: Role Isolation ──────────────────────────────────────────
// Low-confidence events are emitted for student and professor AI analyses.
// Admin and system roles do not generate AI report outputs.
const ALLOWED_ROLES = ['student', 'professor'];

const item = $input.first();
const role = (item.json.payload || {}).role || '';

if (!ALLOWED_ROLES.includes(role)) {
  console.error(JSON.stringify({
    level: 'error', message: 'role_rejected',
    role, allowed: ALLOWED_ROLES,
    event_id: item.json.event_id,
  }));
  throw new Error(`Role '${role}' is not permitted in the low-confidence workflow. Allowed: ${ALLOWED_ROLES.join(', ')}`);
}

return [{ json: { ...item.json, _role_validated: true } }];

// Parse the low-confidence event and classify severity tier.
// critical  : confidence < 0.25  — human review required (HITL)
// high      : 0.25 <= confidence < 0.35  — escalation to professor/admin
// moderate  : 0.35 <= confidence < 0.45  — flag in report, no interrupt
const item    = $input.first();
const payload = item.json.payload || {};

const confidence  = typeof payload.confidence_score === 'number' ? payload.confidence_score : 0;
const threshold   = typeof payload.confidence_threshold === 'number' ? payload.confidence_threshold : 0.45;
const delta       = threshold - confidence;

let severity, escalation_required;
if (confidence < 0.25) {
  severity = 'critical'; escalation_required = true;
} else if (confidence < 0.35) {
  severity = 'high';     escalation_required = true;
} else {
  severity = 'moderate'; escalation_required = false;
}

console.log(JSON.stringify({
  level: 'info', message: 'low_confidence_classified',
  event_id:       item.json.event_id,
  confidence,
  threshold,
  severity,
  escalation_required,
}));

return [{
  json: {
    event_id:        item.json.event_id,
    correlation_id:  item.json.correlation_id,
    payload,
    severity,
    confidence,
    threshold,
    delta:           Math.round(delta * 1000) / 1000,
    escalation_required,
    _idempotency_key: item.json._idempotency_key,
  }
}];

// Build the escalation record sent to the backend.
// For critical severity the HITL workflow should be triggered separately.
const item    = $input.first();
const payload = item.json.payload || {};

const record = {
  id:             `esc-${item.json.event_id}`,
  created_at:     new Date().toISOString(),
  event_id:       item.json.event_id,
  correlation_id: item.json.correlation_id,
  file_id:        payload.file_id  || '',
  user_id:        payload.user_id  || '',
  role:           payload.role     || '',
  confidence:     item.json.confidence,
  threshold:      item.json.threshold,
  delta:          item.json.delta,
  severity:       item.json.severity,
  model_id:       payload.model_id || '',
  safe_mode:      payload.safe_mode || false,
  requires_review: item.json.severity === 'critical',
  status:         'open',
};

return [{ json: { escalation: record, severity: item.json.severity, event_id: item.json.event_id } }];

const item = $input.first();
console.log(JSON.stringify({
  level: 'info', message: 'low_confidence_accepted_no_escalation',
  event_id:       item.json.event_id,
  confidence:     item.json.confidence,
  severity:       item.json.severity,
}));
return [{ json: { status: 'accepted_no_escalation', ...item.json } }];
